"""Export chart source events from the arrangement that renders Cloud Hop."""
import argparse
import json
from pathlib import Path

from synth_tracks import cloud_hop

parser = argparse.ArgumentParser()
parser.add_argument("--check", action="store_true")
args = parser.parse_args()
events: list[tuple[float, float, int, str]] = []
cloud_hop(events)
target = Path(__file__).resolve().parents[2] / "src/content/cloudHopScore.generated.ts"
data = (
    "// Generated by tools/music/export_cloud_hop_score.py; do not edit.\n"
    "type ScoreEvent = readonly [beat: number, duration: number, midi: number, role: 'lead' | 'bass'];\n"
    "export const cloudHopScore: readonly ScoreEvent[] = [\n"
    + "".join("  " + json.dumps(event) + ",\n" for event in sorted(events))
    + "];\n"
)
if args.check:
    if not target.exists() or target.read_text(encoding="utf-8") != data:
        raise SystemExit("Cloud Hop score export is stale")
else:
    target.write_text(data, encoding="utf-8")
print(f"Cloud Hop: {len(events)} audible source events")
